static int btf_parse_hdr(struct btf *btf)
{
        struct btf_header *hdr = btf->hdr;
        __u32 meta_left;

        if (btf->raw_size < sizeof(struct btf_header)) {
                pr_debug("BTF header not found\n");
                return -EINVAL;
        }

        if (hdr->magic == bswap_16(BTF_MAGIC)) {
                btf->swapped_endian = true;
                if (bswap_32(hdr->hdr_len) != sizeof(struct btf_header)) {
                        pr_warn("Can't load BTF with non-native endianness due to unsupported header length %u\n",
                                bswap_32(hdr->hdr_len));
                        return -ENOTSUP;
                }
                btf_bswap_hdr(hdr);
        } else if (hdr->magic != BTF_MAGIC) {
                pr_debug("Invalid BTF magic: %x\n", hdr->magic);
                return -EINVAL;
        }

        if (btf->raw_size < hdr->hdr_len) {
                pr_debug("BTF header len %u larger than data size %u\n",
                         hdr->hdr_len, btf->raw_size);
                return -EINVAL;
        }

        meta_left = btf->raw_size - hdr->hdr_len;
        if (meta_left < (long long)hdr->str_off + hdr->str_len) {
                pr_debug("Invalid BTF total size: %u\n", btf->raw_size);
                return -EINVAL;
        }

        if ((long long)hdr->type_off + hdr->type_len > hdr->str_off) {
                pr_debug("Invalid BTF data sections layout: type data at %u + %u, strings data at %u + %u\n",
                         hdr->type_off, hdr->type_len, hdr->str_off, hdr->str_len);
                return -EINVAL;
        }

--- more ---

        if (hdr->type_off % 4) {
                pr_debug("BTF type section is not aligned to 4 bytes\n");
                return -EINVAL;
        }

        return 0;
}

static int btf_parse_str_sec(struct btf *btf)
{
        const struct btf_header *hdr = btf->hdr;
        const char *start = btf->strs_data;
        const char *end = start + btf->hdr->str_len;

        if (btf->base_btf && hdr->str_len == 0)
                return 0;
        if (!hdr->str_len || hdr->str_len - 1 > BTF_MAX_STR_OFFSET || end[-1]) {
                pr_debug("Invalid BTF string section\n");
                return -EINVAL;
        }
        if (!btf->base_btf && start[0]) {
                pr_debug("Invalid BTF string section\n");
                return -EINVAL;
        }
        return 0;
}

static int btf_type_size(const struct btf_type *t)
{
        const int base_size = sizeof(struct btf_type);
        __u16 vlen = btf_vlen(t);

        switch (btf_kind(t)) {
        case BTF_KIND_FWD:
        case BTF_KIND_CONST:
        case BTF_KIND_VOLATILE:
        case BTF_KIND_RESTRICT:
        case BTF_KIND_PTR:
        case BTF_KIND_TYPEDEF:
        case BTF_KIND_FUNC:
        case BTF_KIND_FLOAT:
        case BTF_KIND_TYPE_TAG:
                return base_size;
        case BTF_KIND_INT:
                return base_size + sizeof(__u32);
        case BTF_KIND_ENUM:
                return base_size + vlen * sizeof(struct btf_enum);
        case BTF_KIND_ARRAY:
                return base_size + sizeof(struct btf_array);
        case BTF_KIND_STRUCT:
        case BTF_KIND_UNION:
                return base_size + vlen * sizeof(struct btf_member);
        case BTF_KIND_FUNC_PROTO:
                return base_size + vlen * sizeof(struct btf_param);
        case BTF_KIND_VAR:
                return base_size + sizeof(struct btf_var);
        case BTF_KIND_DATASEC:
                return base_size + vlen * sizeof(struct btf_var_secinfo);
        case BTF_KIND_DECL_TAG:
                return base_size + sizeof(struct btf_decl_tag);
        default:
                pr_debug("Unsupported BTF_KIND:%u\n", btf_kind(t));
                return -EINVAL;
        }
}

static void btf_bswap_type_base(struct btf_type *t)
{
        t->name_off = bswap_32(t->name_off);
        t->info = bswap_32(t->info);
        t->type = bswap_32(t->type);
}

static int btf_bswap_type_rest(struct btf_type *t)
{
        struct btf_var_secinfo *v;
        struct btf_member *m;
        struct btf_array *a;
        struct btf_param *p;
        struct btf_enum *e;
        __u16 vlen = btf_vlen(t);
        int i;

        switch (btf_kind(t)) {
        case BTF_KIND_FWD:
        case BTF_KIND_CONST:
        case BTF_KIND_VOLATILE:
        case BTF_KIND_RESTRICT:
        case BTF_KIND_PTR:
        case BTF_KIND_TYPEDEF:
        case BTF_KIND_FUNC:
        case BTF_KIND_FLOAT:
        case BTF_KIND_TYPE_TAG:
                return 0;
        case BTF_KIND_INT:
                *(__u32 *)(t + 1) = bswap_32(*(__u32 *)(t + 1));
                return 0;
        case BTF_KIND_ENUM:
                for (i = 0, e = btf_enum(t); i < vlen; i++, e++) {
                        e->name_off = bswap_32(e->name_off);
                        e->val = bswap_32(e->val);
                }
                return 0;
        case BTF_KIND_ARRAY:
                a = btf_array(t);
                a->type = bswap_32(a->type);
                a->index_type = bswap_32(a->index_type);
                a->nelems = bswap_32(a->nelems);
                return 0;
        case BTF_KIND_STRUCT:
        case BTF_KIND_UNION:
                for (i = 0, m = btf_members(t); i < vlen; i++, m++) {
                        m->name_off = bswap_32(m->name_off);
                        m->type = bswap_32(m->type);
                        m->offset = bswap_32(m->offset);
                }
                return 0;
        case BTF_KIND_FUNC_PROTO:
                for (i = 0, p = btf_params(t); i < vlen; i++, p++) {
                        p->name_off = bswap_32(p->name_off);
                        p->type = bswap_32(p->type);
                }
                return 0;
        case BTF_KIND_VAR:
                btf_var(t)->linkage = bswap_32(btf_var(t)->linkage);
                return 0;
        case BTF_KIND_DATASEC:
                for (i = 0, v = btf_var_secinfos(t); i < vlen; i++, v++) {
                        v->type = bswap_32(v->type);
                        v->offset = bswap_32(v->offset);
                        v->size = bswap_32(v->size);
                }
                return 0;
        case BTF_KIND_DECL_TAG:
                btf_decl_tag(t)->component_idx = bswap_32(btf_decl_tag(t)->component_idx);
                return 0;
        default:
                pr_debug("Unsupported BTF_KIND:%u\n", btf_kind(t));
                return -EINVAL;
        }
}

static int btf_parse_type_sec(struct btf *btf)
{
        struct btf_header *hdr = btf->hdr;
        void *next_type = btf->types_data;
        void *end_type = next_type + hdr->type_len;
        int err, type_size;

        while (next_type + sizeof(struct btf_type) <= end_type) {
                if (btf->swapped_endian)
                        btf_bswap_type_base(next_type);

                type_size = btf_type_size(next_type);
                if (type_size < 0)
                        return type_size;
                if (next_type + type_size > end_type) {
                        pr_warn("BTF type [%d] is malformed\n", btf->start_id + btf->nr_types);
                        return -EINVAL;
                }

                if (btf->swapped_endian && btf_bswap_type_rest(next_type))
                        return -EINVAL;

                err = btf_add_type_idx_entry(btf, next_type - btf->types_data);
                if (err)
                        return err;

                next_type += type_size;
                btf->nr_types++;
        }

        if (next_type != end_type) {
                pr_warn("BTF types data is malformed\n");
                return -EINVAL;
        }

        return 0;
}

